; ############################################################################
; NOT code (old 'function table' = the LZ tile-block POINTER TABLE; the payload
; disassembled as instructions is garbage). Overworld/interior MAP data as LZ
; blocks (TileLoad $18A2). Block kinds (decoded):
;   TILESET  2048 B = 128 tiles -> VRAM $9000   (10 blocks)
;   TILEMAP   512 B = 32x16 tile numbers -> WRAM $C300   (6 blocks)
